16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address_line1")
40	    private String addressLine1;
41	
42	    @Column(name = "address_line2")
43	    private String addressLine2;
44	
45	    @Column(name = "address")
46	    @NotEmpty
47	    private String address;
48	
49	    @Column(name = "city")
50	    @NotEmpty
51	    private String city;
52	
53	    @Column(name = "postcode")
54	    private String postcode;
55	
56	    @Column(name = "telephone")
57	    @NotEmpty
58	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
59	    private String telephone;
60	
61	    @Column(name = "email")
62	    @Email
63	    private String email;
64	
65	    @Column(name = "registration_date", columnDefinition = "DATE")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date", columnDefinition = "DATE")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "household_member_count")
81	    private Integer householdMemberCount;
82	
83	    @Column(name = "possible_duplicate")
84	    private Boolean possibleDuplicate;
85	
86	    @Column(name = "possible_duplicate_of")
87	    private Integer possibleDuplicateOf;
88	
89	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
90	    private Set<Pet> pets;
91	
92	    public String getAddressLine1() {
93	        return this.addressLine1;
94	    }
95	
96	    public void setAddressLine1(String addressLine1) {
97	        this.addressLine1 = addressLine1;
98	    }
99	
100	    public String getAddressLine2() {
101	        return this.addressLine2;
102	    }
103	
104	    public void setAddressLine2(String addressLine2) {
105	        this.addressLine2 = addressLine2;
106	    }
107	
108	    public String getAddress() {
109	        return this.address;
110	    }
111	
112	    public void setAddress(String address) {
113	        this.address = address;
114	    }
115	
116	    public String getCity() {
117	        return this.city;
118	    }
119	
120	    public void setCity(String city) {
121	        this.city = city;
122	    }
123	
124	    public String getPostcode() {
125	        return this.postcode;
126	    }
127	
128	    public void setPostcode(String postcode) {
129	        this.postcode = postcode;
130	    }
131	
132	    public String getTelephone() {
133	        return this.telephone;
134	    }
135	
136	    public void setTelephone(String telephone) {
137	        this.telephone = telephone;
138	    }
139	
140	    public String getEmail() {
141	        return this.email;
142	    }
143	
144	    public void setEmail(String email) {
145	        this.email = email;
146	    }
147	
148	    /** Whether this owner has a non-blank email address. */
149	    public boolean hasEmail() {
150	        return this.email != null && !this.email.isBlank();
151	    }
152	
153	    public LocalDate getRegistrationDate() {
154	        return this.registrationDate;
155	    }
156	
157	    public void setRegistrationDate(LocalDate registrationDate) {
158	        this.registrationDate = registrationDate;
159	    }
160	
161	    public LocalDate getBirthDate() {
162	        return this.birthDate;
163	    }
164	
165	    public void setBirthDate(LocalDate birthDate) {
166	        this.birthDate = birthDate;
167	    }
168	
169	    public String getCustomerCode() {
170	        return this.customerCode;
171	    }
172	
173	    public void setCustomerCode(String customerCode) {
174	        this.customerCode = customerCode;
175	    }
176	
177	    public String getHouseholdId() {
178	        return this.householdId;
179	    }
180	
181	    public void setHouseholdId(String householdId) {
182	        this.householdId = householdId;
183	    }
184	
185	    public Integer getNamesakeCount() {
186	        return this.namesakeCount;
187	    }
188	
189	    public void setNamesakeCount(Integer namesakeCount) {
190	        this.namesakeCount = namesakeCount;
191	    }
192	
193	    public Integer getHouseholdMemberCount() {
194	        return this.householdMemberCount;
195	    }
196	
197	    public void setHouseholdMemberCount(Integer householdMemberCount) {
198	        this.householdMemberCount = householdMemberCount;
199	    }
200	
201	    public Boolean getPossibleDuplicate() {
202	        return this.possibleDuplicate;
203	    }
204	
205	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
206	        this.possibleDuplicate = possibleDuplicate;
207	    }
208	
209	    public Integer getPossibleDuplicateOf() {
210	        return this.possibleDuplicateOf;
211	    }
212	
213	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
214	        this.possibleDuplicateOf = possibleDuplicateOf;
215	    }
216	
217	    protected Set<Pet> getPetsInternal() {
218	        if (this.pets == null) {
219	            this.pets = new HashSet<>();
220	        }
221	        return this.pets;
222	    }
223	
224	    protected void setPetsInternal(Set<Pet> pets) {
225	        this.pets = pets;
226	    }
227	
228	    public List<Pet> getPets() {
229	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
230	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
231	        return Collections.unmodifiableList(sortedPets);
232	    }
233	
234	    public void setPets(List<Pet> pets) {
235	        this.pets = new HashSet<>(pets);
236	    }
237	
238	    public void addPet(Pet pet) {
239	        getPetsInternal().add(pet);
240	        pet.setOwner(this);
241	    }
242	
243	    /**
244	     * Return the Pet with the given name, or null if none found for this Owner.
245	     *
246	     * @param name to test
247	     * @return true if pet name is already in use
248	     */
249	    public Pet getPet(String name) {
250	        return getPet(name, false);
251	    }
252	
253	    /**
254	     * Return the Pet with the given name, or null if none found for this Owner.
255	     *
256	     * @param name to test
257	     * @return true if pet name is already in use
258	     */
259	    public Pet getPet(String name, boolean ignoreNew) {
260	        name = name.toLowerCase();
261	        for (Pet pet : getPetsInternal()) {
262	            if (!ignoreNew || !pet.isNew()) {
263	                String compName = pet.getName();
264	                compName = compName.toLowerCase();
265	                if (compName.equals(name)) {
266	                    return pet;
267	                }
268	            }
269	        }
270	        return null;
271	    }
272	
273	    public Pet getPet(Integer petId) {
274	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
275	    }
276	
277	    @Override
278	    public String toString() {
279	        return new ToStringCreator(this)
280	
281	            .append("id", this.getId())
282	            .append("new", this.isNew())
283	            .append("lastName", this.getLastName())
284	            .append("firstName", this.getFirstName())
285	            .append("addressLine1", this.addressLine1)
286	            .append("addressLine2", this.addressLine2)
287	            .append("address", this.address)
288	            .append("city", this.city)
289	            .append("postcode", this.postcode)
290	            .append("telephone", this.telephone)
291	            .append("email", this.email)
292	            .append("registrationDate", this.registrationDate)
293	            .append("birthDate", this.birthDate)
294	            .append("customerCode", this.customerCode)
295	            .append("householdId", this.householdId)
296	            .append("namesakeCount", this.namesakeCount)
297	            .append("householdMemberCount", this.householdMemberCount)
298	            .append("possibleDuplicate", this.possibleDuplicate)
299	            .append("possibleDuplicateOf", this.possibleDuplicateOf)
300	            .toString();
301	    }
302	}
