1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.AgeBand;
8	import org.springframework.samples.petclinic.model.CityRegion;
9	import org.springframework.samples.petclinic.model.ContactPreference;
10	import org.springframework.samples.petclinic.model.Luhn;
11	import org.springframework.samples.petclinic.model.MembershipLevel;
12	import org.springframework.samples.petclinic.model.MembershipNumber;
13	import org.springframework.samples.petclinic.model.Owner;
14	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
15	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
16	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
17	
18	import java.util.Collection;
19	import java.util.List;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName",
28	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
29	    @Mapping(target = "initials", expression = "java(initials(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
34	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
35	    @Mapping(target = "locality", expression = "java(locality(owner))")
36	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
37	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
38	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
39	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    /**
43	     * The upper-cased first letters of the first and last name, dot-separated with a
44	     * trailing dot, e.g. {@code J.S.}.
45	     */
46	    default String initials(Owner owner) {
47	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
48	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
49	    }
50	
51	    /**
52	     * The owner's stored E.164 telephone number formatted for humans as the country code, a
53	     * space, then the national digits grouped in threes (e.g. {@code +61 412 345 678}). The
54	     * raw {@code telephone} field stays in E.164 form.
55	     */
56	    default String telephoneDisplay(Owner owner) {
57	        return org.springframework.samples.petclinic.rest.function.owner.Telephones
58	            .toDisplay(owner.getTelephone());
59	    }
60	
61	    /**
62	     * The Luhn check digit computed over the digits of the owner's customer code.
63	     */
64	    default int checkDigit(Owner owner) {
65	        return Luhn.checkDigit(owner.getCustomerCode());
66	    }
67	
68	    /**
69	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
70	     * {@code YY} is the last two digits of the registration date year, e.g.
71	     * {@code SMI-0007-M26}.
72	     */
73	    default String membershipNumber(Owner owner) {
74	        return MembershipNumber.of(owner);
75	    }
76	
77	    /**
78	     * The owner's membership points, as defined by {@link MembershipLevel}.
79	     */
80	    default int membershipPoints(Owner owner) {
81	        return MembershipLevel.points(owner);
82	    }
83	
84	    /**
85	     * The owner's membership level from 1 to 4, as defined by {@link MembershipLevel}.
86	     */
87	    default int membershipLevel(Owner owner) {
88	        return MembershipLevel.of(owner);
89	    }
90	
91	    /**
92	     * The region the owner's customer code was minted in — its {@code <REGION>} segment
93	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.CustomerCode}).
94	     * Owners without a customer code (e.g. legacy records) fall back to deriving the region
95	     * from the postcode and city directly.
96	     */
97	    default String locality(Owner owner) {
98	        String customerCode = owner.getCustomerCode();
99	        if (customerCode == null || customerCode.isBlank()) {
100	            return CityRegion.localityOf(owner.getPostcode(), owner.getCity());
101	        }
102	        return org.springframework.samples.petclinic.rest.function.owner.CustomerCode
103	            .region(customerCode);
104	    }
105	
106	    /**
107	     * The owner's IANA timezone, derived from their {@link #locality(Owner) locality} via
108	     * the pinned region-to-timezone table (NSW -> Australia/Sydney, VIC ->
109	     * Australia/Melbourne, QLD -> Australia/Brisbane), or {@code null} when the locality
110	     * resolves to no known region.
111	     */
112	    default String timezone(Owner owner) {
113	        return CityRegion.timezoneOf(locality(owner));
114	    }
115	
116	    /**
117	     * How the owner prefers to be contacted: {@code EMAIL} when an email address is
118	     * present, otherwise {@code PHONE}.
119	     */
120	    default String contactPreference(Owner owner) {
121	        return ContactPreference.of(owner).name();
122	    }
123	
124	    /**
125	     * The owner's age band derived from their birth date against their registration date
126	     * (see {@link AgeBand}), or {@code null} when no birth date was supplied.
127	     */
128	    default String ageBand(Owner owner) {
129	        AgeBand ageBand = AgeBand.of(owner);
130	        return ageBand == null ? null : ageBand.name();
131	    }
132	
133	    /**
134	     * The owner's derived identity key used for duplicate detection (see
135	     * {@link org.springframework.samples.petclinic.rest.function.owner.IdentityKeys}).
136	     */
137	    default String identityKey(Owner owner) {
138	        return org.springframework.samples.petclinic.rest.function.owner.IdentityKeys.of(owner);
139	    }
140	
141	    @Mapping(target = "householdMemberCount", ignore = true)
142	    Owner toOwner(OwnerDto ownerDto);
143	
144	    @Mapping(target = "id", ignore = true)
145	    @Mapping(target = "pets", ignore = true)
146	    @Mapping(target = "customerCode", ignore = true)
147	    @Mapping(target = "householdId", ignore = true)
148	    @Mapping(target = "namesakeCount", ignore = true)
149	    @Mapping(target = "householdMemberCount", ignore = true)
150	    Owner toOwner(OwnerFieldsDto ownerDto);
151	
152	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
153	
154	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
155	
156	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
157	        OwnerPageDto ownerPageDto = new OwnerPageDto();
158	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
159	        ownerPageDto.setPage(ownerPage.getNumber());
160	        ownerPageDto.setSize(ownerPage.getSize());
161	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
162	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
163	        return ownerPageDto;
164	    }
165	}
