10	        owner.setAddressLine1(request.getAddressLine1());
11	        owner.setAddressLine2(request.getAddressLine2());
12	        owner.setAddress(Addresses.canonical(request.getAddressLine1(),
13	                request.getAddressLine2(), request.getAddress()));
14	        owner.setCity(request.getCity());
15	        owner.setPostcode(request.getPostcode());
16	        owner.setFirstName(request.getFirstName());
17	        owner.setLastName(request.getLastName());
18	        owner.setTelephone(request.getTelephone());
19	        owner.setEmail(request.getEmail());
20	    }
21	}
