1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Rejects a create request that is missing or blank in any required field
12	 * (firstName, lastName, address, city, telephone) before {@link BuildOwner} maps the
13	 * body, reporting every offending field at once. An address may be supplied in either
14	 * form — a non-blank structured {@code addressLine1} or the flat {@code address} — and
15	 * the request is accepted when at least one is present, keeping earlier minimal owners
16	 * backward-compatible. Publishes the body for later steps so the request is bound only
17	 * here.
18	 */
19	public class ValidateOwnerFields {
20	
21	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
22	            throws MissingOwnerFieldsException {
23	        List<String> missing = new ArrayList<>();
24	        requireText(missing, "firstName", request.getFirstName());
25	        requireText(missing, "lastName", request.getLastName());
26	        // Accept an address in either form; the canonical value is blank only when neither
27	        // the structured addressLine1 nor the flat address supplies one (see Addresses).
28	        requireText(missing, "address", Addresses.canonical(request.getAddressLine1(),
29	                request.getAddressLine2(), request.getAddress()));
30	        requireText(missing, "city", request.getCity());
31	        requireText(missing, "telephone", request.getTelephone());
32	        if (!missing.isEmpty()) {
33	            throw new MissingOwnerFieldsException(missing);
34	        }
35	        validated.set(request);
36	    }
37	
38	    private static void requireText(List<String> missing, String field, String value) {
39	        if (value == null || value.isBlank()) {
40	            missing.add(field);
41	        }
42	    }
43	}
