2	
3	import java.util.List;
4	
5	import org.slf4j.LoggerFactory;
6	
7	import ch.qos.logback.classic.Logger;
8	import ch.qos.logback.classic.spi.ILoggingEvent;
9	import ch.qos.logback.core.read.ListAppender;
10	
11	/**
12	 * Captures events published to the dedicated {@code AUDIT} logger so audit
13	 * side-effects can be asserted without an implementation-specific hook.
14	 *
15	 * <pre>{@code
16	 * try (AuditLogCapture audit = new AuditLogCapture()) {
17	 *     createOwnerOk(validOwner());
18	 *     assertThat(audit.anyContains("...")).isTrue();
19	 * }
20	 * }</pre>
21	 *
22	 * Assumes the logging backend is Logback (the Spring Boot default). If a
23	 * checkpoint logs to a differently-named logger, adjust the name here.
24	 */
25	public final class AuditLogCapture implements AutoCloseable {
26	
27		private final Logger logger;
28	
29		private final ListAppender<ILoggingEvent> appender = new ListAppender<>();
30	
31		public AuditLogCapture() {
32			this("AUDIT");
33		}
34	
35		public AuditLogCapture(String loggerName) {
36			this.logger = (Logger) LoggerFactory.getLogger(loggerName);
37			this.appender.start();
38			this.logger.addAppender(this.appender);
39		}
40	
41		public List<String> messages() {
42			return this.appender.list.stream().map(ILoggingEvent::getFormattedMessage).toList();
43		}
44	
45		public boolean anyContains(String... substrings) {
46			return messages().stream().anyMatch(m -> {
47				for (String s : substrings) {
48					if (!m.contains(s)) {
49						return false;
50					}
51				}
52				return true;
53			});
54		}
55	
56		/** True if some event at the given level (e.g. "WARN") contains all substrings. */
57		public boolean anyAtLevel(String level, String... substrings) {
58			return this.appender.list.stream()
59					.filter(e -> e.getLevel().toString().equalsIgnoreCase(level))
60					.map(ILoggingEvent::getFormattedMessage)
61					.anyMatch(m -> {
62						for (String s : substrings) {
63							if (!m.contains(s)) {
64								return false;
65							}
66						}
67						return true;
68					});
69		}
70	
71		public int count() {
72			return this.appender.list.size();
73		}
74	
75		@Override
76		public void close() {
77			this.logger.detachAppender(this.appender);
78		}
79	}
